import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Scene placement
  group.position.set(
    config.scenePosition.x,
    config.scenePosition.y,
    config.scenePosition.z
  );
  group.rotation.set(
    config.sceneRotation.x,
    config.sceneRotation.y,
    config.sceneRotation.z
  );
  group.scale.set(
    config.sceneScale.x,
    config.sceneScale.y,
    config.sceneScale.z
  );

  // Texture plane
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  const img = texture.image;
  const srcRect = config.atlasRegion?.sourceRect || { x: 0, y: 0, w: 512, h: 320 };
  if (img) {
    texture.offset.set(srcRect.x / img.width, srcRect.y / img.height);
    texture.repeat.set(srcRect.w / img.width, srcRect.h / img.height);
  } else {
    // Fallback if image not yet available
    texture.offset.set(0, 0);
    texture.repeat.set(1, 1);
  }

  const geometry = new THREE.PlaneGeometry(1, 1);
  const material = new THREE.MeshBasicNodeMaterial({ map: texture });
  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Text label (MSDF)
  const textMesh = ctx.fontAtlas.createText('Journal 2', {
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: 0.34,               // headline token size in scene units
    color: config.colors.ink,
    align: 'center',
    justify: 'center'
  });
  textMesh.position.set(0, 0, 0.01); // slight Z offset over card
  group.add(textMesh);

  // Interaction state
  const originalY = group.position.y;
  group.userData.originalY = originalY;

  // Event handlers
  group.userData.handlers = {
    onPointerEnter: () => {
      gsap.to(group.position, {
        y: group.userData.originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto'
      });
    },
    onPointerLeave: () => {
      gsap.to(group.position, {
        y: group.userData.originalY,
        duration: 0.5,
        ease: 'power2.out',
        overwrite: 'auto'
      });
    },
    onClick: () => {
      // Press‑down scale
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1,
            y: 1,
            z: 1,
            duration: 0.4,
            ease: 'back.out',
            overwrite: 'auto'
          });
        }
      });
      // Emit navigation event
      group.userData.event = 'hub-journal.select';
    }
  };

  // Apply cinematic primitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      ctx.primitives[primitive.name](group, primitive.params);
    });
  }

  // Cleanup
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    geometry.dispose();
    material.dispose();
    texture.dispose();
    // Dispose nested meshes (text, children)
    group.traverse((child) => {
      if (child.isMesh) {
        child.material?.dispose();
        child.geometry?.dispose();
      }
    });
  };

  return group;
}
